use corpse_core::{Actor, Floor, population, pocket_biomes, sub_biomes_generation as sb, non_euclidean_generation as ne, portals_generation as pg, startup};
fn room(depth:u32)->Floor{let mut f=Floor{depth:depth as f64,domain:"Dungeon".into(),tiles:vec!["floor".into();2291],lights:vec![0.;2291],seen:vec![false;2291],..Default::default()};for at in 0..2291{if at%79==0||at%79==78||at/79==0||at/79==28{f.tiles[at]="wall".into()}}f.tiles[80]="up".into();f.tiles[27*79+77]="down".into();f}
fn actor(kind:&str,id:f64,x:f64,y:f64)->Actor{population::create_actor_revision(kind,id,x,y,false,37.).unwrap()}
#[test]
fn terrain_is_population_driven_and_historical_revisions_are_untouched(){let mut f=room(30);let mut actors=vec![actor("wendigo",10.,20.,10.),actor("yeti",11.,55.,15.),actor("dryad",12.,35.,10.)];let before=f.clone();let mut id=30.;sb::decorate("habitats",&mut f,&mut actors,&[],&mut id,36.).unwrap();assert_eq!(f,before);sb::decorate("habitats",&mut f,&mut actors,&[],&mut id,37.).unwrap();assert!(pocket_biomes::validate(&f));for a in actors.iter().filter(|a|a.creature_kind.as_ref().is_some_and(|k|k=="wendigo"||k=="yeti")){let at=a.y as usize*79+a.x as usize;assert_eq!(pocket_biomes::at(&f,at).unwrap().theme,"mountainous");assert!(f.ice.as_ref().unwrap()[at]);assert!(f.snow.as_ref().unwrap()[at]);}assert!(f.tiles.iter().any(|t|t=="chasm"));let forest=f.pocket_biomes.as_ref().unwrap().iter().find(|b|b.theme=="forest").unwrap();assert!(forest.cells.iter().any(|i|f.tiles[*i]=="tree"));assert!(forest.cells.iter().any(|i|f.tiles[*i]=="grass"));let once=f.clone();sb::decorate("other",&mut f,&mut actors,&[],&mut id,37.).unwrap();assert_eq!(f,once);}
#[test]
fn hellfire_starts_at25_and_replaces_only_interior_walls(){for depth in [24,25]{let mut f=room(depth);for y in 5..20{f.tiles[y*79+30]="wall".into();}let before=f.tiles.clone();sb::decorate("hellfire",&mut f,&mut vec![],&[],&mut 100.,37.).unwrap();let cells:Vec<_>=f.hellfire.as_ref().unwrap().iter().enumerate().filter_map(|(i,v)|v.then_some(i)).collect();assert_eq!(cells.len(),if depth==25{6}else{0});for i in cells{assert_eq!(before[i],"wall");assert_eq!(f.tiles[i],"floor");assert!(f.environment.as_ref().unwrap().fire[i]>0.0);assert!(i%79>1&&i%79<77&&i/79>1&&i/79<27);}}}
#[test]
fn corn_circles_have_eight_residents_and_highest_depth_eligible_odd_horns(){for depth in [29,36,40]{let mut found=0;for seed in 0..12{let mut f=room(depth);let mut actors=vec![];let mut id=100.;sb::decorate(&seed.to_string(),&mut f,&mut actors,&[],&mut id,37.).unwrap();let Some(c)=f.pocket_biomes.as_ref().into_iter().flatten().find(|b|b.theme=="corn-dimension")else{continue};found+=1;assert_eq!(c.cells.len(),81);let local:Vec<_>=actors.iter().filter(|a|c.cells.contains(&(a.y as usize*79+a.x as usize))).collect();assert!(local.len()>=8);let required=if depth>=36{"horn-7"}else{"horn-5"};assert!(local.iter().any(|a|a.creature_kind.as_ref().is_some_and(|k|k==required)));assert!(local.iter().all(|a|!a.heartless.value_or(false)));}assert!(found>0,"depth{depth}");}}
#[test]
fn speedup_links_are_ordered_deterministic_and_route_safe(){let mut f=room(20);sb::install_links("shortcuts",&mut f,&[],&[],37.);assert_eq!(f.speed_up.as_ref().unwrap().len(),2);assert!(ne::traversable(&f));for p in f.speed_up.as_ref().unwrap(){assert!(p.groups.iter().all(|g|g.sources.len()==1));let low=*p.cells.first().unwrap();let next=p.cells[1];assert_eq!(ne::exits(&f,low),vec![next]);assert_eq!(ne::exits(&f,next),vec![low]);for pair in p.cells.chunks_exact(2){assert_eq!(ne::exits(&f,pair[0]),vec![pair[1]]);assert_eq!(ne::exits(&f,pair[1]),vec![pair[0]]);}}let mut second=room(20);sb::install_links("shortcuts",&mut second,&[],&[],37.);assert_eq!(f,second);let once=f.clone();sb::install_links("different",&mut f,&[],&[],37.);assert_eq!(f,once);let mut shallow=room(19);sb::install_links("shortcuts",&mut shallow,&[],&[],37.);assert!(shallow.speed_up.is_missing());}
#[test]
fn actual_population_sweep_has_safe_links_and_preserves_every_ice_spawn(){let mut counts=[0usize;6];for seed in ["sub-biome-review-1","sub-biome-review-2"]{let mut r=startup::new_run_shell_revision(seed,"Unblessed",false,37.).unwrap();startup::ensure_floors(&mut r,40).unwrap();for f in &r.floors{assert!(pocket_biomes::validate(f),"{seed}:{}",f.depth);assert!(ne::validate_floor(f));assert!(pg::all_endpoints_optional(f));if ne::has_links(f){assert!(ne::traversable(f),"{seed}:{}",f.depth);}for a in &**r.actors.get(&(f.depth as u32).to_string()).unwrap(){if a.creature_kind.as_ref().is_some_and(|k|k=="wendigo"||k=="yeti"){let at=a.y as usize*f.width()+a.x as usize;assert_eq!(pocket_biomes::at(f,at).unwrap().theme,"mountainous");counts[0]+=1;}}for b in f.pocket_biomes.as_ref().into_iter().flatten(){if b.theme=="forest"{counts[1]+=1;counts[5]+=b.cells.iter().filter(|i|matches!(f.tiles[**i].as_str(),"tree"|"grass")).count();}if b.theme=="corn-dimension"{counts[2]+=1;let ports=f.portals.as_ref().into_iter().flatten().filter(|p|b.cells.contains(&p.a)&&b.cells.contains(&p.b)).count();let speeds=f.speed_up.as_ref().into_iter().flatten().filter(|p|p.cells.iter().all(|i|b.cells.contains(i))).count();let random=f.non_euclidean.as_ref().into_iter().flatten().filter(|p|p.cells.iter().all(|i|b.cells.contains(i))).count();assert!(ports>=2&&speeds>=1&&random>=1,"{seed}:{} corn sparse portals{ports} speed{speeds} random{random}",f.depth);}}counts[3]+=f.hellfire.as_ref().unwrap().iter().filter(|v|**v).count();counts[4]+=f.speed_up.as_ref().map_or(0,Vec::len);}}assert!(counts.iter().all(|v|*v>0),"{counts:?}");}
#[test]
fn generated_corn_floor_accepts_a_turn_and_exact_save_resume(){
    let mut run=startup::create_run_revision("sub-biome-review-1","Unblessed",true,37.).unwrap();startup::ensure_floors(&mut run,40).unwrap();let mut tested=0;
    for depth in 29..=40{let f=&run.floors[depth-1];if !f.pocket_biomes.as_ref().into_iter().flatten().any(|b|b.theme=="corn-dimension"){continue}let mut r=run.clone();r.depth=depth as f64;let at=f.tiles.iter().position(|t|t=="up").unwrap();r.player.x=(at%f.width())as f64;r.player.y=(at/f.width())as f64;let mut engine=corpse_core::temporal::Engine::new(r).unwrap();assert!(engine.dispatch(&corpse_core::Command::Wait).unwrap().took_turn);let saved=engine.save().unwrap();assert_eq!(corpse_core::temporal::Engine::load(&saved).unwrap().save().unwrap(),saved);tested+=1;}
    assert!(tested>0);
}
